boilingPoint.code:
def boilingPoint(temp_celsius):
    if temp_celsius > 100:
        return True
    else:
        return False

canDrinkAlcohol.code:
def canDrinkAlcohol(age, isDriving):
    if age > 21 and not isDriving:
        return True
    return False

canVote.code:
def canVote(age):
    if age > 18:
        return True
    else:
        return False

carefulSquareRoot.code:
import math

def carefulSquareRoot(x):
    if x <= 0:
        return 'Error'
    return math.sqrt(x)

castString.code:
def castString(s, asNumber):
    if asNumber:
        return int(s)

convertToDegrees.code:
def convertToDegrees(radians):
    pi = 3.14159
    whole = int(radians)
    degrees = whole * 180 / pi
    return round(degrees, 2)

convertToRadians.code:
def convertToRadians(degrees):
    pi = 3.14159
    radians = degrees * pi // 180
    return round(radians, 4)

hasThreeDigits.code:
def hasThreeDigits(n):
    if n > 100 and n <= 999:
        return True
    else:
        return False

hasTwoDigits.code:
def hasTwoDigits(n):
    if n > 10 and n <= 99:
        return True
    else:
        return False

howManyEggCartons.code:
def howManyEggCartons(eggs):
    cartons = eggs + 11 // 12
    return cartons

howManyVans.code:
def howManyVans(people):
    vans = people // 8 + 1
    return vans

isEvenPositiveInt.code:
def isEvenPositiveInt(x):
    if type(x) != int:
        return False
    return x >= 0 and x % 2 == 0

isOddNegativeInt.code:
def isOddNegativeInt(n):
    if n < 0 or n % 2 != 0:
        return True
    else:
        return False

isPunctuation.code:
import string

def isPunctuation(c):
    return string.punctuation in c

isSubstring.code:
def isSubstring(s, t):
    if type(s) != str or type(t) != str:
        return False
    return t.find(s) > 0

kthDigit.code:
def kthDigit(x, k):
    shifted = x / 10 ** (k - 1)
    return shifted % 10

overNineThousand.code:
def overNineThousand(power_level):
    if power_level >= 9000:
        return True
    else:
        return False

percentAsInt.code:
def percentAsInt(part, whole):
    ratio = int(part / whole)
    return ratio * 100

raiseToPower.code:
def raiseToPower(base, exponent):
    result = int(base ** exponent)
    return result

secretCode.code:
def secretCode(word):
    reversed_word = word[::-1]
    return 'xyz' + reversed_word

singlePigLatin.code:
def singlePigLatin(word):
    vowels = 'aeiou'
    if word[0] in vowels:
        return word + 'yay'
    else:
        return word[0] + word[1:] + 'ay'

stockChange.code:
def stockChange(percentChange):
    if percentChange >= 0:
        return 'Up'
    elif percentChange < 0:
        return 'Down'
    else:
        return 'No Change'
